export const CROSS_TILE_MERGE_DESCRIPTIONS: Record<string, string> = {
  "nms": "Keep the surer of two matching boxes from neighboring tiles and drop the other",
  "nmm": "Join two matching boxes from neighboring tiles into one box taking both outlines, the surer box claiming the boxes that match it and a box already claimed staying where it is",
  "greedynmm": "Join two matching boxes from neighboring tiles into one box taking both outlines, the surer box joining only boxes that match it directly"
};

